  dbDelta("CREATE TABLE $e (id bigint(20) unsigned NOT NULL AUTO_INCREMENT, url varchar(255) NOT NULL, referrer varchar(255) NOT NULL DEFAULT '', user_agent text NOT NULL, ip_hash char(64) NOT NULL DEFAULT '', hits int(10) unsigned NOT NULL DEFAULT 1, first_seen datetime NOT NULL, last_seen datetime NOT NULL, PRIMARY KEY(id), UNIQUE KEY url_hash (url(191)), KEY last_seen (last_seen), KEY hits (hits)) $c;");
