 }
 public static function tables_exist():bool{global $wpdb;$tables=[$wpdb->prefix.'seom_redirects',$wpdb->prefix.'seom_404_logs',$wpdb->prefix.'seom_audit',$wpdb->prefix.'seom_indexing_logs'];foreach($tables as $t){$found=$wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s',$t));if($found!==$t)return false;}return true;}
